(function(){'use strict';window.SpinnerManager={show: function(containerId){const container=containerId ? document.getElementById(containerId): document.getElementById('results');if(!container)return;let spinner=container.querySelector('.spinner-overlay');if(!spinner){spinner=this.createSpinner();container.style.position='relative';container.insertBefore(spinner,container.firstChild);}spinner.style.display='flex';},hide: function(containerId){const container=containerId ? document.getElementById(containerId): document.getElementById('results');if(!container)return;const spinner=container.querySelector('.spinner-overlay');if(spinner){spinner.style.display='none';}},createSpinner: function(){const spinnerDiv=document.createElement('div');spinnerDiv.className='spinner-overlay';spinnerDiv.innerHTML=`<div class="spinner-container"><div class="spinner"></div><p class="spinner-text">Calculating...</p></div>`;return spinnerDiv;},showOnButton: function(buttonId){const button=typeof buttonId==='string' ?
document.getElementById(buttonId): buttonId;if(!button)return;button.dataset.originalText=button.innerHTML;button.innerHTML=`<span class="button-spinner"></span><span>Calculating...</span>`;button.disabled=true;button.classList.add('calculating');},hideFromButton: function(buttonId){const button=typeof buttonId==='string' ?
document.getElementById(buttonId): buttonId;if(!button)return;if(button.dataset.originalText){button.innerHTML=button.dataset.originalText;}button.disabled=false;button.classList.remove('calculating');}};window.calculateWithSpinner=function(calculationFunction,options){options=options||{};const buttonId=options.buttonId||'calculate';const delay=options.delay||300;SpinnerManager.showOnButton(buttonId);setTimeout(()=>{const startTime=Date.now();try{const result=calculationFunction();const elapsed=Date.now()-startTime;const remainingDelay=Math.max(0,delay-elapsed);setTimeout(()=>{SpinnerManager.hideFromButton(buttonId);},remainingDelay);}catch(error){SpinnerManager.hideFromButton(buttonId);console.error('Calculation error:',error);throw error;}},10);};})();